<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue'
import {useRouter} from 'vue-router'
import type {QForm} from 'quasar'
import {matArrowBack,matSave} from '@quasar/extras/material-icons'
import {request} from '../lib/api'
import ConfigFields from '../components/ConfigFields.vue'
import type {Bootstrap,ScanConfig,Proxy,CredentialSet,Profile,Schedule,Page} from '../types'
const props=defineProps<{kind:'profiles'|'schedules';id?:string}>(),router=useRouter(),form=ref<QForm|null>(null)
const boot=ref<Bootstrap|null>(null),config=ref<ScanConfig|null>(null),proxies=ref<Proxy[]>([]),credentials=ref<CredentialSet[]>([]),profiles=ref<Profile[]>([])
const misfire=ref('skip'),overlap=ref('skip')
const name=ref(''),cron=ref('0 9 * * *'),timezone=ref(Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC'),enabled=ref(false),authorized=ref(false),copyID=ref(''),loading=ref(true),saving=ref(false),error=ref('')
const schedule=computed(()=>props.kind==='schedules'),title=computed(()=>`${props.id?'Edit':'New'} ${schedule.value?'schedule':'scan profile'}`)
let controller:AbortController|undefined
function clone<T>(v:T):T{return JSON.parse(JSON.stringify(v))}
async function load(){controller?.abort();controller=new AbortController();const signal=controller.signal;loading.value=true;error.value='';boot.value=null;config.value=null;authorized.value=false;enabled.value=false;name.value='';try{const [b,p,c,list,existing]=await Promise.all([request<Bootstrap>('/bootstrap',{signal}),request<Page<Proxy>>('/proxies',{signal}),request<Page<CredentialSet>>('/credential-sets',{signal}),request<Page<Profile>>('/profiles',{signal}),props.id?request<Profile|Schedule>(`/${props.kind}/${encodeURIComponent(props.id)}`,{signal}):Promise.resolve(null)]);if(signal.aborted)return;boot.value=b;proxies.value=p.items;credentials.value=c.items;profiles.value=list.items;const saved=existing;if(props.id&&!saved)throw new Error('This saved configuration no longer exists. Return to the list and refresh.');config.value=clone(saved?.config??b.defaults);const defaults=c.items.find(s=>s.name.startsWith('CCTVScan defaults'));if(!saved&&defaults&&b.policy.allow_credentials===true){config.value.credential_set_id=defaults.id;config.value.check_credentials=true}name.value=saved?.name??'';if(schedule.value&&saved){const s=saved as Schedule;cron.value=s.cron;timezone.value=s.timezone;enabled.value=s.enabled;misfire.value=s.misfire_policy??'skip';overlap.value=s.overlap_policy??'skip'}}catch(e){if(!signal.aborted)error.value=e instanceof Error?e.message:'Could not load this configuration.'}finally{if(!signal.aborted)loading.value=false}}
function copyProfile(id:string){const p=profiles.value.find(v=>v.id===id);if(p){config.value=clone(p.config);authorized.value=false}}
watch(config,()=>{authorized.value=false},{deep:true})
async function save(){if(saving.value||!config.value)return;if(schedule.value&&enabled.value&&!authorized.value){error.value='Confirm authorization before enabling recurring work.';return}if(!await form.value?.validate())return;saving.value=true;error.value='';try{await request(`/${props.kind}${props.id?'/'+encodeURIComponent(props.id):''}`,{method:props.id?'PUT':'POST',body:{name:name.value.trim(),config:clone(config.value),...(schedule.value?{cron:cron.value.trim(),timezone:timezone.value.trim(),enabled:enabled.value,misfire_policy:misfire.value,overlap_policy:overlap.value}:{})},signal:controller?.signal});await router.push(`/${props.kind}`)}catch(e){if(!controller?.signal.aborted)error.value=e instanceof Error?e.message:'The configuration could not be saved.'}finally{saving.value=false}}
watch(()=>[props.kind,props.id],load);onMounted(load);onBeforeUnmount(()=>controller?.abort())
</script>
<template>
 <q-page class="workspace editor-workspace"><header class="page-header"><div><q-btn flat dense class="back-link" :icon="matArrowBack" :label="schedule?'Schedules':'Scan profiles'" @click="router.push('/'+kind)"/><h1>{{title}}</h1><p class="page-description">{{schedule?'Keep recurring work explicit, bounded and tied to a named timezone.':'Save a complete, reusable configuration. This action does not queue a scan.'}}</p></div></header>
  <div v-if="error" class="error-banner" role="alert"><span>{{error}}</span><q-btn v-if="!config" flat label="Try again" @click="load"/></div><div v-if="loading" class="loading-label" role="status">Loading saved configuration and current server policy…</div>
  <q-form v-else-if="config&&boot" ref="form" class="editor-layout" @submit="save"><div class="surface editor-form"><section class="form-section"><h2>{{schedule?'Schedule identity':'Profile identity'}}</h2><q-input v-model="name" name="configuration_name" outlined :label="schedule?'Schedule name':'Profile name'" maxlength="200" :rules="[v=>!!String(v).trim()||'Enter a name.']"/><q-select v-if="profiles.length" class="q-mt-md" v-model="copyID" @update:model-value="copyProfile" outlined emit-value map-options label="Copy configuration from a profile" :options="profiles.map(p=>({label:p.name,value:p.id}))" hint="This copies its current values; future profile edits do not change this saved configuration."/></section><ConfigFields v-model="config" :policy="boot.policy" :proxies="proxies" :credential-sets="credentials"/></div>
   <aside class="surface editor-aside"><span class="section-label">{{schedule?'Recurring execution':'Stored configuration'}}</span><template v-if="schedule"><h2>A time and<br>a clear boundary.</h2><q-input class="q-mt-lg" v-model="cron" outlined label="Five-field cron expression" placeholder="0 9 * * *" :rules="[v=>String(v).trim().split(/\s+/).length===5||'Use minute hour day month weekday.']" hint="minute · hour · day of month · month · weekday"/><q-input class="q-mt-lg" v-model="timezone" outlined label="IANA timezone" :rules="[v=>!!String(v).trim()||'Choose a timezone.']" hint="For example: Asia/Colombo, Europe/London or UTC."/><q-select v-model="misfire" class="q-mt-lg" outlined emit-value map-options label="If an execution is missed" :options="[{label:'Skip missed occurrence',value:'skip'},{label:'Queue one catch-up only',value:'catch_up_once'}]" hint="Never replays every missed interval."/><q-select v-model="overlap" class="q-mt-lg" outlined emit-value map-options label="If a previous occurrence is active" :options="[{label:'Skip overlapping occurrence',value:'skip'},{label:'Queue for later',value:'queue'}]" hint="Queued work still obeys the global execution budget."/><div class="inspector-rule"/><q-toggle v-model="enabled" color="dark" label="Enable recurring execution"/><p class="helper q-mt-sm">New schedules start paused unless you explicitly enable them. Due work queues once per occurrence; actual start depends on a runner.</p><q-checkbox v-if="enabled" v-model="authorized" color="dark" class="q-mt-md" label="I authorize recurring work for this complete scope and all enabled actions."/><p v-if="id&&enabled" class="safe-note q-mt-lg">Editing does not pause the current schedule until you save. Already queued jobs keep their original configuration.</p></template><template v-else><h2>A repeatable<br>starting point.</h2><p class="helper q-mt-md">A profile stores settings and secret references, never plaintext credentials.</p><div class="inspector-rule"/><p class="helper">Creating a job from a profile copies its configuration. Existing jobs do not change when you edit this profile.</p></template><q-btn data-testid="save-configuration" type="submit" class="full-width q-mt-lg" unelevated color="primary" text-color="dark" :icon="matSave" :label="schedule?(enabled?'Save enabled schedule':'Save paused schedule'):'Save profile'" :loading="saving" :disable="schedule&&enabled&&!authorized"/><q-btn class="full-width q-mt-sm" flat label="Cancel" :disable="saving" @click="router.push('/'+kind)"/></aside>
  </q-form>
 </q-page>
</template>
<style scoped>.editor-workspace{max-width:1520px}.back-link{margin-left:-9px;margin-bottom:22px;color:var(--muted);font-size:12px}.editor-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:24px;align-items:start}.editor-form{padding:28px}.editor-aside{padding:24px;position:sticky;top:24px}.editor-aside h2{margin-top:24px;font-size:26px}.editor-aside .q-checkbox{font-size:12px;line-height:1.6}@media(max-width:1150px){.editor-layout{grid-template-columns:minmax(0,1fr) 270px;gap:18px}.editor-form{padding:23px}.editor-aside{padding:20px}}@media(max-width:800px){.editor-layout{grid-template-columns:1fr}.editor-aside{position:static}.editor-form{padding:22px 18px}}</style>
